            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#E1E4E8\">  StripeTerminal,</span>",
            "<span style=\"color:#E1E4E8\">  TerminalConnectTypes,</span>",
            "<span style=\"color:#E1E4E8\">  TerminalEventsEnum,</span>",
            "<span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe-terminal'</span><span style=\"color:#E1E4E8\">;</span>",
            "",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> paymentStatusListener</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
            "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.PaymentStatusChange,</span>",
            "<span style=\"color:#E1E4E8\">  ({ </span><span style=\"color:#FFAB70\">status</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(status),</span>",
            "<span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> confirmedListener</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
