            "<span style=\"color:#E1E4E8\">);</span>",
            "",
            "<span style=\"color:#a0aab5\">// Register the authenticated RequestedConnectionToken provider first.</span>",
            "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">initialize</span><span style=\"color:#E1E4E8\">({ isTest: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\"> });</span>",
            "",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">readers</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">discoverReaders</span><span style=\"color:#E1E4E8\">({</span>",
