            "<span style=\"color:#E1E4E8\">});</span>",
            "",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> reader</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> readers[</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">];</span>",
