            "<span style=\"color:#E1E4E8\">});</span>",
            "",
            "<span style=\"color:#F97583\">try</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> response</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'https://example.com/connection/intent'</span><span style=\"color:#E1E4E8\">, {</span>",
